$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
if (-not $IsWindows -or $PSVersionTable.PSVersion.Major -lt 7) { throw 'Windows pwsh 7 required' }
$feature = 'f8805ab2a80105080edec95d215768b96a25f4ce'
$checkout = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$testPath = '.github/github_actions/tools/test_duplicate_function_action_contract.py'
$paths = @(
    $testPath
    '.github/actions/run-duplicate-function-check/action.yml'
    '.github/actions/run-duplicate-function-check/Invoke-DcoirDuplicateFunctionCheck.ps1'
    '.github/actions/run-duplicate-function-check/DuplicateFunctionCheck.Paths.ps1'
    '.github/scripts/Test-DuplicateFunctionCheckPaths.ps1'
    '.github/scripts/Get-CollectorSourcePartFiles.ps1'
    '.github/actions/validate-powershell-syntax/action.yml'
    '.github/workflows/reusable-validate-on-pr.yml'
    '.github/workflows/reusable-validate-on-push.yml'
)
$probe = @(git -C $checkout cat-file -e "${feature}^{commit}" 2>&1)
if ($LASTEXITCODE -ne 0) {
    $fetched = @(git -C $checkout fetch --no-tags origin $feature 2>&1)
    if ($LASTEXITCODE -ne 0) { throw "Pinned feature fetch failed: $($fetched -join ' ')" }
}
$verified = git -C $checkout rev-parse "${feature}^{commit}"
if ($LASTEXITCODE -ne 0 -or $verified -cne $feature) { throw 'Pinned feature commit mismatch' }
$expected = @{
    $testPath = 'aa7f52b45ab63411db13a659eb7c973e95f73c71'
    '.github/actions/run-duplicate-function-check/Invoke-DcoirDuplicateFunctionCheck.ps1' = 'd9aad00f353f9facaeb9485cfe331c0a71ca4684'
    '.github/actions/run-duplicate-function-check/DuplicateFunctionCheck.Paths.ps1' = 'ef4b036aa676af3234bb24662e165d6a22afd776'
    '.github/scripts/Test-DuplicateFunctionCheckPaths.ps1' = 'cf33df7c969b4b25493f68a6d60321ea4cfa7146'
}
$tree = @(git -C $checkout ls-tree -r $feature -- @paths)
if ($LASTEXITCODE -ne 0 -or $tree.Count -ne $paths.Count) { throw 'Unexpected pinned fixture tree' }
$start = (Get-Location).Path
$scratch = Join-Path ([IO.Path]::GetTempPath()) ('dcoir-608-driver-green-' + [guid]::NewGuid().ToString('N'))
$owned = $false
$utf8 = [Text.UTF8Encoding]::new($false)
# Exact reviewed candidate source, gzip/base64 solely for bounded transport.
$payload = ''
$expectedHash = 'e68f965919b482f501ef658f9a44f3c750c22fcd5344f92c2e39086bec445a20'
$inputStream = [IO.MemoryStream]::new([Convert]::FromBase64String($payload))
$outputStream = [IO.MemoryStream]::new()
try {
    $gzip = [IO.Compression.GZipStream]::new($inputStream,[IO.Compression.CompressionMode]::Decompress)
    try { $gzip.CopyTo($outputStream) } finally { $gzip.Dispose() }
    $candidate = $outputStream.ToArray()
} finally { $outputStream.Dispose(); $inputStream.Dispose() }
if ($candidate.Length -ne 10251 -or [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($candidate)).ToLowerInvariant() -cne $expectedHash) { throw 'Candidate source bytes mismatch' }
try {
    if (Test-Path -LiteralPath $scratch) { throw 'Scratch path already exists' }
    New-Item -ItemType Directory -Path $scratch -ErrorAction Stop | Out-Null
    $owned = $true
    $archive = Join-Path $scratch 'fixture.zip'
    $repo = Join-Path $scratch 'repo'
    git -C $checkout -c core.autocrlf=false archive --format=zip "--output=$archive" $feature -- @paths
    if ($LASTEXITCODE -ne 0 -or -not [IO.File]::Exists($archive)) { throw 'Pinned fixture archive failed' }
    [IO.Compression.ZipFile]::ExtractToDirectory($archive,$repo)
    $seen = @{}
    foreach ($entry in $tree) {
        $m = [regex]::Match($entry,'^100(644|755) blob ([0-9a-f]{40})\t([A-Za-z0-9_./-]+)$')
        if (-not $m.Success) { throw 'Unexpected fixture tree entry' }
        $rel = $m.Groups[3].Value
        if ($rel -notin $paths -or $seen.ContainsKey($rel) -or $rel -match '(^|/)\.\.?(/|$)') { throw 'Unexpected fixture path' }
        $seen[$rel] = $true
        $file = Join-Path $repo $rel
        $item = Get-Item -LiteralPath $file -Force -ErrorAction Stop
        if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Nonregular fixture file' }
        $raw = git -C $checkout hash-object --no-filters -- $file
        if ($LASTEXITCODE -ne 0 -or $raw -cne $m.Groups[2].Value -or ($expected.ContainsKey($rel) -and $raw -cne $expected[$rel])) { throw "Fixture blob mismatch: $rel" }
    }
    if ($seen.Count -ne $paths.Count) { throw 'Fixture path count mismatch' }
    $test = Join-Path $repo $testPath
    [IO.File]::WriteAllBytes($test,$candidate)
    if ((Get-FileHash -LiteralPath $test -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedHash) { throw 'Written driver hash mismatch' }
    Set-Location -LiteralPath $repo
    $stdout = Join-Path $scratch 'python-stdout.txt'
    $stderr = Join-Path $scratch 'python-stderr.txt'
    python $test -v 1> $stdout 2> $stderr
    $exit = $LASTEXITCODE
    $nativeOutput = [IO.File]::ReadAllText($stdout)
    $unitOutput = [IO.File]::ReadAllText($stderr)
    Write-Output $unitOutput
    Write-Output $nativeOutput
    $marker = 'DCOIR_DUPLICATE_PATH_TEST_PASS positive=12 rejected=54 markdown=9'
    $records = @($nativeOutput -split '\r?\n' | Where-Object { $_.TrimStart().StartsWith('DCOIR_DUPLICATE_PATH_TEST_PASS',[StringComparison]::Ordinal) })
    if ($exit -ne 0 -or $unitOutput -notmatch '(?m)^Ran 15 tests? in ' -or $unitOutput -notmatch '(?m)^OK\s*$' -or $records.Count -ne 1 -or $records[0] -cne $marker) { throw 'Expected full Windows driver GREEN not observed' }
    if ($unitOutput -notmatch '(?m)^test_shipped_powershell_behavior .* \.\.\. ok\r?$' -or $unitOutput -match '(?im)^.*skipped.*$') { throw 'Windows native execution evidence missing or skipped' }
    if ((Get-FileHash -LiteralPath $test -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedHash) { throw 'Driver changed during validation' }
    Write-Output "DRIVER_GREEN_COMPLETE structural=9 mocked=5 native=1 exit=$exit sha256=$expectedHash bytes=$($candidate.Length) feature=$feature pwsh=$($PSVersionTable.PSVersion)"
} finally {
    Set-Location -LiteralPath $start
    if ($owned) { Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction Stop }
}
Write-Output 'DRIVER_GREEN_SCRATCH_CLEANUP_COMPLETE'
$global:LASTEXITCODE = 0

